// Settings: edit these before going live.
const settings = {
  company_name: 'Palm Grove Realty',
  telegram_urgent_chat_id: 'YOUR_OPS_CHAT_ID',
  // Haiku: one short classification per email, high volume. Use claude-sonnet-5-5 if triage quality is not enough.
  anthropic_model: 'claude-haiku-5-5',
  // Provider: anthropic | gemini. Gemini Flash-Lite is the Haiku-class option.
  llm_provider: 'anthropic',
  gemini_model: 'gemini-3.5-flash-lite',
  // Gmail label IDs (Gmail node > Labels > Get many, or the label dropdown). Empty = no label.
  label_ids: { sales: '', support: '', billing: '', complaint: '', newsletter: '', spam: '', other: '', urgent: '' },
};

const j = $input.first().json;
// Webhook items always carry webhookUrl; Gmail trigger items never do. Never trust the payload for this.
const fromGmail = !('webhookUrl' in j);
const q = j.query || {};
const body = fromGmail ? {} : (j.body || {});
const dryRun = !fromGmail && ['1', 'true', 'yes'].includes(String(q.dry_run ?? body.dry_run ?? '').toLowerCase());

function parseFrom(v) {
  const m = String(v || '').match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
  return m ? { name: m[1].trim(), email: m[2].trim().toLowerCase() } : { name: '', email: String(v || '').trim().toLowerCase() };
}

const from = fromGmail
  ? { name: j.from?.value?.[0]?.name || '', email: (j.from?.value?.[0]?.address || '').toLowerCase() }
  : parseFrom(body.from);
const text = String(fromGmail ? (j.text || j.snippet || '') : (body.body || '')).replace(/\s+\n/g, '\n').trim().slice(0, 4000);

return [{ json: {
  settings, dry_run: dryRun, source: fromGmail ? 'gmail' : 'webhook',
  gmail_id: fromGmail ? j.id : null, thread_id: fromGmail ? j.threadId : null,
  from_name: from.name, from_email: from.email, subject: String((fromGmail ? j.subject : body.subject) || '').trim(), body: text,
} }];

function claudeRequest(model, body) {
  const fallback = !/^claude-haiku/.test(model);
  return {
    claude_body: { model, ...body, ...(fallback ? { fallbacks: 'default' } : {}) },
    claude_headers: { 'anthropic-version': '2026-10-21', ...(fallback ? { 'anthropic-beta': 'server-side-fallback-2026-07-01' } : {}) },
  };
}

// Gemini's responseSchema takes the same JSON schema minus additionalProperties.
function geminiSchema(schema) {
  if (Array.isArray(schema)) return schema.map(geminiSchema);
  if (!schema || typeof schema !== 'object') return schema;
  return Object.fromEntries(Object.entries(schema).filter(([k]) => k !== 'additionalProperties').map(([k, v]) => [k, geminiSchema(v)]));
}
function llmRequest(s, { system, user, schema, max_tokens }) {
  if (s.llm_provider === 'gemini') {
    return {
      llm_provider: 'gemini',
      gemini_url: `https://generativelanguage.googleapis.com/v1beta/models/${s.gemini_model}:generateContent`,
      gemini_body: {
        systemInstruction: { parts: [{ text: system }] },
        contents: [{ role: 'user', parts: [{ text: user }] }],
        generationConfig: { responseMimeType: 'application/json', responseSchema: geminiSchema(schema) },
      },
    };
  }
  if (s.llm_provider !== 'anthropic') throw new Error(`llm_provider must be anthropic or gemini, not "${s.llm_provider}"`);
  return {
    llm_provider: 'anthropic',
    ...claudeRequest(s.anthropic_model, {
      max_tokens, output_config: { effort: 'low', format: { type: 'json_schema', schema } }, system,
      messages: [{ role: 'user', content: user }],
    }),
  };
}

// Keyword rules: used for dry runs and as the fallback when Claude fails.
const d = $input.first().json;
const raw = `${d.subject}\n${d.body}`;
const t = raw.toLowerCase();
const arabic = (raw.match(/[؀-ۿ]/g) || []).length;
const letters = (raw.match(/[A-Za-z؀-ۿ]/g) || []).length || 1;
const language = arabic / letters > 0.3 ? 'ar' : 'en';

const CATEGORIES = [
  ['spam', /lottery|winner|crypto|bitcoin|claim your prize|ربحت|جائزة/],
  ['newsletter', /unsubscribe|newsletter|weekly digest|webinar|إلغاء الاشتراك|النشرة/],
  ['complaint', /complain|disappointed|unacceptable|terrible|worst|شكوى|سيء|غير مقبول|زعلان/],
  ['billing', /invoice|payment|refund|charged|receipt|فاتورة|دفع|الدفع|استرداد|مبلغ/],
  ['support', /not working|error|broken|issue|problem|help|can't log|cannot log|لا يعمل|مشكلة|عطل|مساعدة|لا أستطيع/],
  ['sales', /price|quote|quotation|interested|buy|book|availability|عرض سعر|سعر|مهتم|حجز|متوفر/],
];
const category = CATEGORIES.find(([, re]) => re.test(t))?.[0] || 'other';
const urgentWords = /urgent|asap|immediately|today|عاجل|ضروري|فورا|فوراً|اليوم/.test(t);
const priority = ['newsletter', 'spam'].includes(category) ? 'low' : category === 'complaint' || urgentWords ? 'urgent' : 'normal';

const first = d.from_name ? d.from_name.split(' ')[0] : '';
const DRAFTS = {
  en: `Dear ${first || 'Customer'},\n\nThank you for your email about "${d.subject}". We have received it and the right team will reply within one business day.\n\nKind regards,\n${d.settings.company_name}`,
  ar: `${first ? `عزيزي ${first}` : 'عزيزي العميل'}،\n\nشكراً لرسالتك بخصوص "${d.subject}". لقد استلمناها وسيرد عليك الفريق المختص خلال يوم عمل واحد.\n\nمع التحية،\n${d.settings.company_name}`,
};
const summary_en = `${category} email from ${d.from_name || d.from_email}: ${d.subject}`.slice(0, 200);
const triage = { category, priority, language, summary_en, draft_reply: DRAFTS[language] };

const schema = {
  type: 'object', additionalProperties: false,
  required: ['category', 'priority', 'language', 'summary_en', 'draft_reply'],
  properties: {
    category: { type: 'string', enum: ['sales', 'support', 'billing', 'complaint', 'newsletter', 'spam', 'other'] },
    priority: { type: 'string', enum: ['urgent', 'normal', 'low'] },
    language: { type: 'string', enum: ['en', 'ar'] },
    summary_en: { type: 'string', description: 'One sentence in English' },
    draft_reply: { type: 'string', description: 'Short reply in the language of the email' },
  },
};
const request = llmRequest(d.settings, {
  max_tokens: 4096,
  schema,
  system:
    `You triage the shared inbox of ${d.settings.company_name}, a company in the UAE. Emails arrive in Arabic, English or both. ` +
    'Priority is urgent for complaints, outages, legal or payment failures, or explicit deadlines today. ' +
    'Write the draft reply in the language of the email: acknowledge the request, say the team will follow up within one business day, ' +
    'and never promise refunds, prices, discounts or dates.',
  user: `From: ${d.from_name} <${d.from_email}>\nSubject: ${d.subject}\n\n${d.body}`,
});

return [{ json: { ...d, triage, triage_source: 'rules', ...request } }];

const BLOCKED = ['SAFETY', 'PROHIBITED_CONTENT', 'BLOCKLIST', 'SPII', 'RECITATION'];
function readLLM(res) {
  if (!res || res.error) {
    const msg = res?.error?.message || JSON.stringify(res?.error);
    // n8n replaces the API message on 429, so check the whole error (status code, description, cause).
    const limited = /429|rate.?limit|RESOURCE_EXHAUSTED|quota|spacing your requests/i.test(JSON.stringify(res?.error));
    throw new Error(`${limited ? 'rate limited (429) after retries' : 'request failed'}: ${msg}`);
  }
  if (res.candidates || res.promptFeedback) {  // Gemini generateContent
    const c = res.candidates?.[0];
    if (res.promptFeedback?.blockReason || BLOCKED.includes(c?.finishReason)) throw new Error('model declined the request');
    const text = (c?.content?.parts || []).filter((p) => p.text && !p.thought).map((p) => p.text).join('');
    if (!text) throw new Error('no text in response');
    return JSON.parse(text);
  }
  if (res.stop_reason === 'refusal') throw new Error('model declined the request');  // Claude Messages
  const text = [...(res.content || [])].reverse().find((b) => b.type === 'text')?.text;
  if (!text) throw new Error('no text block in response');
  return JSON.parse(text);
}
const PROVIDER_NAME = { anthropic: 'Claude', gemini: 'Gemini' };
const SOURCE = { anthropic: 'claude', gemini: 'gemini' };

const base = $('Classify with rules').first().json;
try {
  return [{ json: { ...base, triage: readLLM($input.first().json), triage_source: SOURCE[base.llm_provider] } }];
} catch (e) {
  return [{ json: { ...base, triage_note: `${PROVIDER_NAME[base.llm_provider]} failed, used rules: ${e.message}` } }];
}

const d = $input.first().json;
const t = d.triage;
const ids = d.settings.label_ids;
const label_ids = [ids[t.category], t.priority === 'urgent' ? ids.urgent : ''].filter(Boolean);
const wants_draft = ['sales', 'support', 'billing', 'complaint'].includes(t.category);
const alert = t.priority === 'urgent';
const alert_text = [
  `Urgent ${t.category} email (${t.language.toUpperCase()})`,
  `From: ${d.from_name} <${d.from_email}>`,
  `Subject: ${d.subject}`,
  `Summary: ${t.summary_en}`,
].join('\n');
return [{ json: {
  dry_run: d.dry_run, source: d.source, gmail_id: d.gmail_id, thread_id: d.thread_id,
  from_email: d.from_email, subject: d.subject, ...t,
  label_ids, draft_reply: wants_draft ? t.draft_reply : null, alert, alert_text,
  triage_source: d.triage_source, triage_note: d.triage_note || '',
} }];
